/**
 * Version of @nexusmods/vortex-api the extension is built against, injected by rolldown
 */
declare const __VORTEX_API_VERSION__: string;

/**
 * The extension's version from its package.json, injected by rolldown
 */
declare const __EXTENSION_VERSION__: string;

/**
 * The extension's name as Vortex shows it, config.extensionName in its package.json, injected by rolldown
 */
declare const __EXTENSION_NAME__: string;
